export const notificationViewPage = {
  id: 'notification-view',
  slug: 'notification-view'
}

// The opening run stops at the hub once every prerequisite section is
  // answered but the review gate itself needs a manual visit.
  ...
    .getByRole('link', { name: 'Check and submit', exact: true })

sections: {
    consignment: '1. About the consignment',
    arrival: '2. Arrival and destination',
    parties: '3. Consignment parties'
  },

{% for card in section.cards %}
      {{ govukSummaryList({
        card: { title: { text: card.title, headingLevel: 3 }, actions: card.actions },
        rows: card.rows
      }) }}

typeLabels: {
    potatoes: 'Potatoes (seed or ware)',
    'plants-for-planting': 'Plants for planting',
    'wood-and-cut-trees': 'Wood and cut trees'
  },

const originCountryLabel = await countries.originLabel(
    answers.countryOfOrigin
  )

actions.items[0].href = detailsHref(
        { params: { journeyId }, query: { change: '1' } },
        { index }
      )

statusLabels: {
    'already-arrived': 'Yes, it has already arrived',
    'not-yet-arrived': 'No, it has not arrived yet'
  }

const proposedPlaceOfLandingLabel = scope.has('proposedPlaceOfLanding')
    ? await ports.label(answers.proposedPlaceOfLanding)
    : undefined

const NOT_PROVIDED = copy.notProvided

export const valueText = (value) => {
  if (isBlank(value)) {
    return NOT_PROVIDED

errors: {
    parties: {
      consignor: 'Select an address for the consignor',
      placeOfDestination: 'Select an address for the place of destination'
    }
  },

if (Object.keys(errors).length > 0) {
    return (await render(request, h, current, false)).code(
      HTTP_STATUS_BAD_REQUEST
    )
  }

if (!current.scope.readyForCheckYourAnswers) {
    return h.redirect(hubPath(current.journey.journeyId))
  }

submit: {
    heading: 'Now submit your notification',
    body: 'Continue to the declaration to submit your notification.'
  },

{% if lateNotification %}
    {% set lateBody %}
      <h2 class="govuk-notification-banner__heading">{{ copy.late.heading }}</h2>
      <p class="govuk-body">{{ lateRule }} {{ copy.late.accepted }}</p>

if (current.journey.status === state.SUBMITTED) {
    return h.redirect(pagePath(current.journey.journeyId, page.slug))
  }

// Ruled c-030: AMEND offers Cancel amendment instead of Delete; the
    // success banner shows once, after cancel-amend's own redirect.
    cancelAmendHref:
      current.journey.status === state.AMEND
        ? pagePath(current.journey.journeyId, 'cancel-amend')
        : null,

{% if amendmentCancelled %}
    {{ govukNotificationBanner({
      type: "success",
      titleText: copy.cancelAmend.successTitle,
      text: copy.cancelAmend.successBody,
      role: "alert"

new Date(value).toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
    timeZone: 'Europe/London'
  })

if (journey.status === state.SUBMITTED) {
    return h.redirect(pagePath(journey.journeyId, 'confirmation'))
  }

...(journey.status === state.DRAFT && {
          lateNotificationIndicator: lateness(
            requestClock(request),
            answers.commodityType,
            answers.arrivalDate
          )
        })

if (!result.ok) {
    return h.redirect(pagePath(journey.journeyId, kit.CYA_SLUG))
  }

if (journey.status !== state.SUBMITTED) {
    return h.redirect(pagePath(journey.journeyId, kit.CYA_SLUG))
  }

{% set referenceHtml %}{{ copy.reference }}<br><strong>{{ reference }}</strong>{% endset %}
  {{ sectionCaption(caption) }}
  {{ govukPanel({ titleText: copy.title, html: referenceHtml }) }}

if (!isRealDate(Number(year), Number(month), Number(day))) {
    return 'on-time'
  }

if (
    !potato &&
    !['plants-for-planting', 'wood-and-cut-trees'].includes(commodityType)
  ) {
    return 'on-time'
  }

const deadline = addUtcDays(
    arrivalDay,
    potato ? -POTATO_DAYS_BEFORE_ARRIVAL : PLANTS_WOOD_DAYS_AFTER_ARRIVAL
  )
  return startOfDayInZone(clock, 'Europe/London') > deadline

export const lateNotificationIndicator = {
  id: 'c9e1043b-7fba-42d2-80c2-6d6384d9630c',
  name: 'lateNotificationIndicator',
  status: 'optional',
  system: true
}

export const evaluationBindings = feature('review', [
  scalar({
    field: 'lateNotificationIndicator',
    obligation: lateNotificationIndicator
  })
])
